"""Orca-aligned linear OCP readout: train=data, validation=readout, test=testdata."""
from __future__ import annotations
import argparse, json, random, logging, traceback
from pathlib import Path
import numpy as np, torch
from src.core.run_context import apply_cli_defaults, task_context
logging.basicConfig(level=logging.INFO, format='%(asctime)s %(levelname)s %(message)s')
LOG = logging.getLogger('videomae2.ocp')

def load(root,split):
 rows=[torch.load(p,map_location='cpu',weights_only=True) for p in sorted((Path(root)/split).glob('*.pt')) if p.name!='manifest.json'];
 if not rows: raise FileNotFoundError(f'no cache samples in {Path(root)/split}')
 x=torch.stack([torch.cat((r['context_latent'].float().mean(dim=0),r['future_latent'].float().mean(dim=0))) for r in rows]); y=torch.tensor([r['ocp_label'] for r in rows],dtype=torch.float32); LOG.info('loaded split=%s samples=%d positives=%d positive_rate=%.4f feature_shape=%s',split,len(y),int(y.sum()),float(y.mean()),tuple(x.shape)); return x,y
def metrics(prob,y,t):
 pred=prob>=t; truth=y.bool(); tp=int((pred&truth).sum()); tn=int((~pred&~truth).sum()); fp=int((pred&~truth).sum()); fn=int((~pred&truth).sum()); pos=max(tp+fn,1); neg=max(tn+fp,1); return {'samples':len(y),'accuracy':(tp+tn)/max(len(y),1),'balanced_accuracy':.5*(tp/pos+tn/neg),'f1':2*tp/max(2*tp+fp+fn,1),'tp':tp,'tn':tn,'fp':fp,'fn':fn}
def main():
 ctx=task_context();p=argparse.ArgumentParser(); p.add_argument('--cache-root',required=True); p.add_argument('--output-dir',required=True); p.add_argument('--epochs',type=int,default=300); p.add_argument('--lr',type=float,default=.01); p.add_argument('--weight-decay',type=float,default=.001); p.add_argument('--seed',type=int,default=239); apply_cli_defaults(p,ctx);a=p.parse_args(); random.seed(a.seed); np.random.seed(a.seed); torch.manual_seed(a.seed); tx,ty=load(a.cache_root,'data_v1'); vx,vy=load(a.cache_root,'readout_data_v1'); ex,ey=load(a.cache_root,'testdata_v1'); mean,std=tx.mean(0,keepdim=True),tx.std(0,keepdim=True).clamp_min(1e-6); net=torch.nn.Linear(tx.size(1),1); opt=torch.optim.AdamW(net.parameters(),lr=a.lr,weight_decay=a.weight_decay); pw=(len(ty)-ty.sum()).clamp_min(1)/ty.sum().clamp_min(1); best=float('inf'); state=None; history=[]
 LOG.info('starting OCP readout: train=data_v1 validation=readout_data_v1 test=testdata_v1 epochs=%d lr=%g weight_decay=%g',a.epochs,a.lr,a.weight_decay)
 for epoch in range(1,a.epochs+1):
  net.train(); loss=torch.nn.functional.binary_cross_entropy_with_logits(net((tx-mean)/std).squeeze(1),ty,pos_weight=pw); opt.zero_grad(); loss.backward(); opt.step(); net.eval(); vl=torch.nn.functional.binary_cross_entropy_with_logits(net((vx-mean)/std).squeeze(1),vy); history.append({'epoch':epoch,'train_split':'data_v1','validation_split':'readout_data_v1','train_loss':float(loss),'validation_loss':float(vl)}); improved=float(vl)<best; state={k:v.detach().clone() for k,v in net.state_dict().items()} if improved else state; best=min(best,float(vl));
  if epoch==1 or improved or epoch%10==0 or epoch==a.epochs: LOG.info('epoch=%d train_loss=%.6f val_loss=%.6f%s',epoch,float(loss),float(vl),' [best]' if improved else '')
 net.load_state_dict(state); valp=torch.sigmoid(net((vx-mean)/std).squeeze(1)); testp=torch.sigmoid(net((ex-mean)/std).squeeze(1)); thresholds=torch.unique(torch.cat((torch.tensor([.5]),valp))).sort().values; threshold=max(((metrics(valp,vy,float(t))['balanced_accuracy'],-abs(float(t)-.5),float(t)) for t in thresholds))[2]; result=metrics(testp,ey,threshold); result.update({'protocol':'videomaev2_physionpp_orca_aligned_groundtruth_future_ocp_v1','train_split':'data_v1','threshold_split':'readout_data_v1','test_split':'testdata_v1','future_latent_source':'ground_truth_future_video','threshold':threshold,'train_samples':len(ty),'validation_samples':len(vy),'test_samples':len(ey),'best_validation_loss':best,'best_epoch':min(range(len(history)),key=lambda i: history[i]['validation_loss'])+1,'validation_probability_min':float(valp.min()),'validation_probability_max':float(valp.max()),'test_probability_min':float(testp.min()),'test_probability_max':float(testp.max()),'validation_metrics':metrics(valp,vy,threshold)}); LOG.info('selected best_epoch=%d best_val_loss=%.6f threshold=%.6f val_prob=[%.6f,%.6f] test_prob=[%.6f,%.6f]',result['best_epoch'],best,threshold,float(valp.min()),float(valp.max()),float(testp.min()),float(testp.max())); LOG.info('final test metrics=%s',json.dumps(result,sort_keys=True)); out=Path(a.output_dir); out.mkdir(parents=True,exist_ok=True); torch.save({'model':net.state_dict(),'mean':mean,'std':std,'threshold':threshold,'protocol':result['protocol']},out/'readout.pt'); (out/'history.json').write_text(json.dumps(history,indent=2)+'\n'); (out/'metrics.json').write_text(json.dumps(result,indent=2)+'\n'); print(json.dumps(result,indent=2))
if __name__=='__main__': main()
